using System;using System.IO;using System.Text.Json;namespace SAUDICO.Federate.Core;public sealed class SettingsService{readonly string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"SAUDICO","Federate","settings.json");public ExportSettings Load(){try{return File.Exists(path)?JsonSerializer.Deserialize<ExportSettings>(File.ReadAllText(path))??ExportSettings.Default():ExportSettings.Default();}catch{try{File.Copy(path,path+".corrupt",true);}catch{}return ExportSettings.Default();}}public void Save(ExportSettings value){Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}));}}